/*!
 * 分布图 / distribution maps — lazy Leaflet map initialiser
 * ---------------------------------------------------------------------------
 * Data: assets/geo/{family,genus}/<id>.geojson (1 degree grid, GBIF occurrences)
 * Generated by .github/workflows/build_occurrence_geojson.py
 *
 * Tile policy (see _tools/分布图与瓦片使用政策.md):
 *  - Leaflet is served locally (assets/vendor/leaflet/), never from a CDN.
 *  - A map is created ONLY when its container scrolls into view
 *    (IntersectionObserver, rootMargin 0) — no off-screen tile prefetching,
 *    no requests for maps the reader never reaches.
 *  - Base map: GBIF's public raster tiles (tile.gbif.org, OSM-derived) with
 *    attribution; if they fail, fall back to OpenStreetMap's tile server with
 *    its attribution and referrerpolicy="no-referrer-when-downgrade".
 *  - maxZoom is capped: the data is a 1 degree grid, deeper zooms add no
 *    information but would cost tiles.
 */
(function () {
  'use strict';

  var GBIF_TILES = 'https://tile.gbif.org/3857/omt/{z}/{x}/{y}@1x.png?style=gbif-natural-en';
  var OSM_TILES = 'https://tile.openstreetmap.org/{z}/{x}/{y}.png';
  var GBIF_ATTR =
    'GBIF base map | &copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors';
  var OSM_ATTR =
    '&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors';
  var MAX_ZOOM = 9;
  var MIN_ZOOM = 1;

  function text(el, name, fallback) {
    var value = el.getAttribute(name);
    return value === null || value === '' ? fallback : value;
  }

  function isEmpty(el) {
    return el.getAttribute('data-map-state') === 'ready';
  }

  function fail(el) {
    if (isEmpty(el)) {
      return;
    }
    el.setAttribute('data-map-state', 'empty');
    el.className += ' is-empty';
    el.innerHTML =
      '<p class="distribution-map-empty">' +
      text(el, 'data-empty', 'No data.') +
      '</p>';
  }

  function markerRadius(n, maxN) {
    var t = Math.sqrt(n / maxN);
    return 2.2 + 9.8 * t;
  }

  function markerFill(n, maxN) {
    return 0.26 + 0.5 * Math.sqrt(n / maxN);
  }

  function addLegend(map, maxN, title) {
    var control = L.control({ position: 'bottomright' });
    control.onAdd = function () {
      var box = L.DomUtil.create('div', 'map-legend');
      var heading = L.DomUtil.create('span', 'map-legend-title', box);
      heading.innerHTML = title;

      var steps = [1, Math.max(1, Math.round(maxN / 6)), maxN];
      var seen = {};
      for (var i = 0; i < steps.length; i++) {
        var n = steps[i];
        if (seen[n]) {
          continue;
        }
        seen[n] = true;
        var row = L.DomUtil.create('div', 'map-legend-row', box);
        var dot = L.DomUtil.create('span', 'map-legend-dot', row);
        var size = Math.round(markerRadius(n, maxN) * 2);
        dot.style.width = size + 'px';
        dot.style.height = size + 'px';
        dot.style.opacity = String(0.35 + markerFill(n, maxN));
        var label = L.DomUtil.create('span', 'map-legend-label', row);
        label.textContent = String(n);
      }
      L.DomEvent.disableClickPropagation(box);
      L.DomEvent.disableScrollPropagation(box);
      return box;
    };
    control.addTo(map);
  }

  function useOsmFallback(map, oldLayer) {
    map.removeLayer(oldLayer);
    var osm = L.tileLayer(OSM_TILES, {
      attribution: OSM_ATTR,
      minZoom: MIN_ZOOM,
      maxZoom: MAX_ZOOM
    });
    osm.on('tileloadstart', function (event) {
      // OSM tile usage policy asks for the referrer to be trimmed, not stripped
      if (event.tile && event.tile.setAttribute) {
        event.tile.setAttribute('referrerpolicy', 'no-referrer-when-downgrade');
      }
    });
    osm.addTo(map);
    if (map.attributionControl) {
      map.attributionControl.removeAttribution(GBIF_ATTR);
    }
  }

  function render(el, data) {
    var features = (data && data.features) || [];
    if (!features.length) {
      fail(el);
      return;
    }

    var maxN = 1;
    for (var i = 0; i < features.length; i++) {
      var value = Number(features[i] && features[i].properties && features[i].properties.n) || 1;
      if (value > maxN) {
        maxN = value;
      }
    }

    var unit = text(el, 'data-unit', 'records');
    el.innerHTML = ''; // drop the "loading" placeholder before Leaflet builds its panes
    var map = L.map(el, {
      scrollWheelZoom: false,
      zoomControl: true,
      minZoom: MIN_ZOOM,
      maxZoom: MAX_ZOOM,
      worldCopyJump: true,
      attributionControl: true
    });

    var base = L.tileLayer(GBIF_TILES, {
      attribution: GBIF_ATTR,
      minZoom: MIN_ZOOM,
      maxZoom: MAX_ZOOM
    });
    var errors = 0;
    var swapped = false;
    base.on('tileerror', function () {
      errors += 1;
      if (!swapped && errors >= 3) {
        swapped = true;
        useOsmFallback(map, base);
      }
    });
    base.addTo(map);

    var layer = L.geoJSON(data, {
      pointToLayer: function (feature, latlng) {
        var n = Number(feature.properties && feature.properties.n) || 1;
        return L.circleMarker(latlng, {
          radius: markerRadius(n, maxN),
          color: '#1f4d38',
          weight: 1,
          opacity: 0.7,
          fillColor: '#2f6b4f',
          fillOpacity: markerFill(n, maxN)
        });
      },
      onEachFeature: function (feature, featureLayer) {
        var n = Number(feature.properties && feature.properties.n) || 0;
        featureLayer.bindPopup('<strong>' + n + '</strong> ' + unit);
      }
    });
    layer.addTo(map);

    var bounds = layer.getBounds();
    if (bounds.isValid()) {
      map.fitBounds(bounds, { padding: [14, 14], maxZoom: 8 });
    } else {
      map.setView([0, 0], 2);
    }

    addLegend(map, maxN, text(el, 'data-legend', 'records / cell'));

    el.setAttribute('data-map-state', 'ready');
    el.className += ' is-ready';
    window.setTimeout(function () {
      map.invalidateSize();
    }, 120);
  }

  function initMap(el) {
    if (el.getAttribute('data-map-state') !== 'idle') {
      return;
    }
    var url = el.getAttribute('data-geojson');
    if (!url) {
      fail(el);
      return;
    }
    el.setAttribute('data-map-state', 'loading');
    if (!window.fetch) {
      fail(el);
      return;
    }
    fetch(url, { credentials: 'same-origin' })
      .then(function (response) {
        if (!response.ok) {
          throw new Error('HTTP ' + response.status);
        }
        return response.json();
      })
      .then(function (data) {
        if (!window.L) {
          throw new Error('Leaflet missing');
        }
        render(el, data);
      })
      .catch(function () {
        fail(el);
      });
  }

  function ensureLeafletCss() {
    // Leaflet's stylesheet must sit next to leaflet.js. The layout normally loads it,
    // but if a page only loads the script the map would collapse -- inject it once here.
    if (document.querySelector('link[href*="leaflet"]')) {
      return;
    }
    var script = document.querySelector('script[src*="leaflet.js"]');
    if (!script) {
      return;
    }
    var src = script.getAttribute('src') || '';
    var link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = src.split('?')[0].replace('leaflet.js', 'leaflet.css');
    document.head.appendChild(link);
  }

  function boot() {
    var nodes = document.querySelectorAll('.distribution-map[data-geojson]');
    if (!nodes.length || !window.L) {
      return;
    }
    ensureLeafletCss();
    if (!('IntersectionObserver' in window)) {
      // No lazy loading available: draw only what the first screen shows.
      for (var i = 0; i < nodes.length; i++) {
        var rect = nodes[i].getBoundingClientRect();
        if (rect.top < window.innerHeight && rect.bottom > 0) {
          initMap(nodes[i]);
        }
      }
      return;
    }
    var observer = new IntersectionObserver(
      function (entries) {
        for (var i = 0; i < entries.length; i++) {
          if (entries[i].isIntersecting) {
            observer.unobserve(entries[i].target);
            initMap(entries[i].target);
          }
        }
      },
      { rootMargin: '0px', threshold: 0 }
    );
    for (var j = 0; j < nodes.length; j++) {
      observer.observe(nodes[j]);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
